<?php
require_once __DIR__.'/../bootstrap.php';
function aniread_sync(string $mode='top'):array{global $pdo,$config;$endpoint=['latest'=>'anime?q=&sfw=true&order_by=mal_id&sort=desc','season'=>'seasons/now','upcoming'=>'seasons/upcoming','top'=>'top/anime','movies'=>'top/anime?type=movie','airing'=>'top/anime?filter=airing'][$mode]??'top/anime';$start=$pdo->prepare('INSERT INTO sync_logs(status,message) VALUES(?,?)');$start->execute(['running','Started '.$mode.' synchronization']);$added=0;$updated=0;$errors=0;$page=1;$max=2;$limit=(int)($config['sync_limit']??12);for(;$page<=$max;$page++){ $url=rtrim($config['jikan_base'],'/').'/'.$endpoint.(str_contains($endpoint,'?')?'&':'?').'page='.$page; $ctx=stream_context_create(['http'=>['timeout'=>20,'header'=>'User-Agent: AniRead/1.0\r\n']]);$raw=@file_get_contents($url,false,$ctx);if(!$raw){$errors++;continue;}$data=json_decode($raw,true)['data']??[];foreach(array_slice($data,0,$limit) as $x){try{$mal=(int)($x['mal_id']??0);if(!$mal)continue;$old=$pdo->prepare('SELECT id FROM anime WHERE mal_id=?');$old->execute([$mal]);$exists=(int)$old->fetchColumn();$sql='INSERT INTO anime(mal_id,title,english_title,japanese_title,synopsis,poster,banner,trailer_url,type,status,episodes,duration,score,rank,popularity,members,favorites,year,season,source,aired_from,aired_to) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE title=VALUES(title),english_title=VALUES(english_title),japanese_title=VALUES(japanese_title),synopsis=VALUES(synopsis),poster=VALUES(poster),banner=VALUES(banner),trailer_url=VALUES(trailer_url),type=VALUES(type),status=VALUES(status),episodes=VALUES(episodes),duration=VALUES(duration),score=VALUES(score),rank=VALUES(rank),popularity=VALUES(popularity),members=VALUES(members),favorites=VALUES(favorites),year=VALUES(year),season=VALUES(season),source=VALUES(source),aired_from=VALUES(aired_from),aired_to=VALUES(aired_to),updated_at=NOW()';$v=[$mal,$x['title']??'Untitled',$x['title_english']??null,$x['title_japanese']??null,$x['synopsis']??null,$x['images']['jpg']['large_image_url']??null,$x['images']['jpg']['large_image_url']??null,$x['trailer']['url']??null,$x['type']??null,$x['status']??null,$x['episodes']??null,$x['duration']??null,$x['score']??null,$x['rank']??null,$x['popularity']??null,$x['members']??null,$x['favorites']??null,$x['year']??null,$x['season']??null,$x['source']??null,!empty($x['aired']['from'])?substr($x['aired']['from'],0,10):null,!empty($x['aired']['to'])?substr($x['aired']['to'],0,10):null];$pdo->prepare($sql)->execute($v);$exists?$updated++:$added++;$id=$exists?:$pdo->lastInsertId();foreach(($x['genres']??[]) as $g){$pdo->prepare('INSERT IGNORE INTO genres(name) VALUES(?)')->execute([$g['name']]);$q=$pdo->prepare('SELECT id FROM genres WHERE name=?');$q->execute([$g['name']]);$pdo->prepare('INSERT IGNORE INTO anime_genres(anime_id,genre_id) VALUES(?,?)')->execute([$id,$q->fetchColumn()]);}}catch(Throwable $e){$errors++;}}if($page<$max)usleep(350000);}$msg="Added $added, updated $updated, errors $errors";$pdo->prepare('INSERT INTO sync_logs(status,message,finished_at) VALUES(?,?,NOW())')->execute([$errors?'partial':'success',$msg]);return compact('added','updated','errors');}
if(PHP_SAPI==='cli'){aniread_sync($argv[1]??'top');}
